"""This file contains classes relating to low level iCOM error handling"""

from interops.libraries.icom.icom_error_codes import *  #TODO - not ideal, find alternative to import all errors codes?
import logging

logger = logging.getLogger(__name__)


class IcomError(RuntimeError):
    '''
    Base class.
    '''
    pass


class IcomConnectionError(IcomError):
    '''General connectivity error'''

    def __init__(self, message, error_number, description):

        self.msg = message
        self.errno = error_number
        self.desc = description

    def __str__(self):
        return self.msg + " [" + str(self.errno) + "] " + str(self.desc)


class IcomTagError(IcomError):
    '''Single tag error'''

    def __init__(self, message, error_number, description):

        self.msg = message
        self.errno = error_number
        self.desc = description

    def __str__(self):
        return self.msg + " [" + str(self.errno) + "] " + str(self.desc)


class IcomMessageError(IcomError):
    '''General send message error'''

    def __init__(self, message, error_number, description):

        self.msg = message
        self.errno = error_number
        self.desc = description

    def __str__(self):
        return self.msg + " [" + str(self.errno) + "] " + str(self.desc)


def exception_from_err(message, error_number):
    '''
    Raises either an IcomConnectionError or IcomTagError depending on the error number.

    '''
    description = decode_dict.get(error_number, "UNKNOWN ERROR")

    # General connection errors
    if error_number in (INVALID_CONNECTION_HANDLE, INVALID_MESSAGE_HANDLE, CONNECTION_IN_PROGRESS,
                        TIMEOUT_ERROR, NOT_CONNECTED, CONNECTION_FAILED, INVALID_PROTOCOL_VERSION,
                        SEND_IN_PROGRESS):
        logger.info("IcomConnectionError -" + str(description))
        return IcomConnectionError(message, error_number, description)

    # FX message validation errors
    if error_number in (INVALID_CONTROL_POINT_NUM, DUPLICATE_ITEM, MISSING_CONTROL_POINT,
                        TOO_MANY_TAGS, INVALID_TAG):
        logger.info("IcomTagError -" + str(description))
        return IcomTagError(message, error_number, description)
